export function roof(g, footprint, style = "hip", o = {}) {
  if (ROOF_PRESETS[style] || o.preset) {                                   // a preset: good options by construction, flags override
    const name = ROOF_PRESETS[style] ? style : o.preset, { preset, ...rest } = o;
    if (!ROOF_PRESETS[name]) throw new Error(`roof: unknown preset ${name} (${Object.keys(ROOF_PRESETS).join(", ")})`);
    const p = presetOptions(name, g, rectsOf(footprint), rest);
    return roof(g, footprint, rest.style && ROOF_STYLES.includes(rest.style) ? rest.style : p.style, { ...p, ...Object.fromEntries(Object.entries(rest).filter(([k]) => k !== "style")), _notes: p._notes, _preset: name });
  }
  if (!ROOF_STYLES.includes(style)) throw new Error(`roof: unknown style ${style} (${ROOF_STYLES.join(", ")})`);
  if (o.y == null) throw new Error("roof: opts.y (the eave course: wall top + 1) is required");
  const rects = rectsOf(footprint), y0 = o.y, W = writer(), notes = [...(o._notes || [])];
  let P = pitchOf(o.pitch ?? 45);
  // material: a palette / mix / block becomes a texture (materialAt by role) unless texture:false or the caller brings a hook
  const texSeed = o.seed ?? 0;
  const baseOf = (n) => { const mix = ROOF_PALETTES[n]?.mix ?? (Array.isArray(n) ? n : n?.mix); return mix ? mix.find((m) => m[2] !== "full")[0] : n; };
  const resolve = (n) => {
    if (o.texture === false || o.materialAt || (typeof n === "string" && NO_STAIRS.test(materialOf(n).prefix))) return { tex: null, base: o.texture === false && o.material == null ? "deepslate_tile" : baseOf(n) };   // texture:false with no material is the legacy single block
    try { const tex = textureOf(n, { seed: texSeed }); return { tex, base: tex.members.find((m) => !m.fullOnly).block }; } catch { return { tex: null, base: baseOf(n) }; }
  };
  const given = o.material ?? DEFAULT_MATERIAL;
  let { tex, base } = resolve(given);
  let mat = materialOf(base);
  const trim = materialOf(o.trim ?? base);
  for (const [label, m] of [["material", mat], ["trim", trim]]) if (NO_STAIRS.test(m.prefix)) notes.push(`${label} ${m.prefix} has no stairs or slabs: the roof would place invalid blocks (use a brick, tile, plank, cut-stone or cut-copper material)`);
  const fc = o.protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
