export const ROOF_PRESETS = {
  cottage: (P) => ({ style: "gable", pitch: P.span <= 11 ? "steep" : 45, steep: true, eave: "flared", material: "spruce", alt: ["dark_oak", "deepslate_tile", "brick"], verge: "dark_oak", ridge: "slab",
    chimneys: [{ at: P.wide ? [P.R[2] - 1, P.R[1] + Math.floor(P.d / 2)] : [P.R[0] + Math.floor(P.w / 2), P.R[3] - 1], material: "cobblestone" }] }),
  shop: (P) => ({ style: "gable", ridgeAxis: P.frontZ ? "z" : "x", pitch: P.span <= 11 ? "steep" : 45, steep: true, eave: "plain", material: "dark_oak", alt: ["spruce", "deepslate_tile", "brick"], verge: "spruce", ridge: "slab",
    dormers: P.span >= 13 && P.len >= 8 ? { face: P.side, count: P.len >= 14 ? 2 : 1, style: "gable" } : undefined }),   // no room on a small steep roof
  townhouse: (P) => ({ style: "mansard", pitch: "steep", lower: Math.max(2, Math.round(P.span / 5)), eave: "cornice", trim: "stone_brick", material: "deepslate_tile", alt: ["dark_oak", "polished_blackstone_brick", "spruce"], ridge: "crest",
    dormers: { face: P.front, count: Math.max(1, Math.round(P.frontLen / 6)), style: "gable" } }),
  civic: (P) => ({ style: "hip", pitch: 45, eave: "cornice", trim: "smooth_quartz", material: "deepslate_tile", alt: ["dark_oak", "brick", "spruce"], ridge: "slab",
    pediment: { face: P.front, width: odd(Math.round(P.frontLen * 0.45), P.frontLen), pitch: 45, tympanum: "smooth_quartz", cornice: "smooth_quartz" } }),
  temple: (P) => ({ style: "gable", ridgeAxis: P.frontZ ? "z" : "x", pitch: "half", eave: "cornice", gableCornice: true, trim: "smooth_quartz", verge: "smooth_quartz", gable: "smooth_quartz",
    material: "brick", alt: ["deepslate_tile", "dark_oak"], ridge: "slab" }),
  granary: (P) => ({ style: "gable", pitch: P.span <= 13 ? "steep" : 45, steep: true, eave: "plain", material: "deepslate_tile", alt: ["dark_oak", "spruce", "brick"], verge: "dark_oak", ridge: "none", monitor: true }),
  modern: () => ({ style: "flat-parapet", parapet: 1, trim: "smooth_stone", eave: "cornice", dentils: false, rail: true, material: "smooth_stone" }),
};
ROOF_PRESETS.industrial = ROOF_PRESETS.granary;
ROOF_PRESETS["flat-parapet-modern"] = ROOF_PRESETS.modern;
applyPresets(ROOF_PRESETS);                                                  // palettes for the old presets, the new type presets (roof-presets.mjs)
const odd = (n, of) => (n % 2 === of % 2 ? n : n + 1);

/** The options a preset gives for this footprint, with size sanity applied. Returns opts (+ _notes). */
export function presetOptions(name, g, rects, o = {}) {
  const R = rects.reduce((a, r) => ((r[2] - r[0]) * (r[3] - r[1]) > (a[2] - a[0]) * (a[3] - a[1]) ? r : a));
  const w = R[2] - R[0] + 1, d = R[3] - R[1] + 1, front = FRONT_FACE(o), frontZ = ZD.has(front);
  const y0 = o.y ?? 0, wallH = wallHeightOf(g, R, y0);
  const P = { R, w, d, span: Math.min(w, d), len: Math.max(w, d), wide: w >= d, front, frontZ, frontLen: frontZ ? w : d, side: frontZ ? "east" : "south", wallH, y0 };
  const opts = { overhang: P.span >= 15 ? 2 : 1, ...ROOF_PRESETS[name](P), _notes: [] };
  // size sanity: on buildings of two storeys or less the roof is no taller than the walls (unless steep by design)
  if (!opts.steep && opts.style !== "flat-parapet" && wallH > 0 && wallH <= 9) {
    const ladder = [3, 2, 1, 0.5];
    let p = pitchOf(opts.pitch ?? 45);
    const height = (pp) => riseFn(opts.style, pp, { ...opts, eave: "plain" }, P.span)(Math.floor((P.span - 1) / 2));
    const down = (q) => ladder.find((l) => l < q - 1e-9);
    while (height(p) > wallH && down(p) != null) p = down(p);
    if (p !== pitchOf(opts.pitch ?? 45)) { opts._notes.push(`${name}: pitch eased to ${p} so the roof is no taller than the ${wallH}-course walls`); opts.pitch = p; }
  }
  delete opts.steep;
  return opts;
}
