  { name: "Bedroom 3", box: [31, 6, 12, 34, 8, 16] },
  { name: "Bedroom 4", box: [19, 6, 21, 22, 8, 24] },
  { name: "Primary bedroom", box: [36, 6, 13, 41, 8, 19] },
  { name: "Primary sitting nook", box: [39, 6, 9, 41, 8, 11] },
  { name: "Primary bath", box: [36, 6, 21, 41, 8, 23] },
