  for (let z = 26; z <= 31; z++) if (z !== 28) g.set(34, 2, z, ...B.fence("spruce"));   // gap: the side steps
  for (const [x, z] of [[19, 26], [34, 26], [19, 31], [34, 31], [26, 31], [19, 28], [34, 28]])
    for (let y = 0; y <= 2; y++) g.set(x, y, z, ...B.log("spruce", "y"));
